// ===== qiankun 主应用 =====
import { registerMicroApps, start } from 'qiankun';

registerMicroApps([
  {
    name: 'react-app',
    entry: '//localhost:3001',
    container: '#micro-container',
    activeRule: '/react',
    props: { token: 'xxx', sharedState: {} } // 通过 props 传递共享数据
  },
  {
    name: 'vue-app',
    entry: '//localhost:3002',
    container: '#micro-container',
    activeRule: '/vue'
  }
]);

// 启动沙箱：strictStyleIsolation 开启 Shadow DOM CSS 隔离
start({ sandbox: { strictStyleIsolation: true } });

// ===== qiankun 子应用（React）必须导出三个生命周期 =====
export async function bootstrap() {
  // 首次加载时执行一次，做全局初始化
  console.log('React app bootstrap');
}

export async function mount(props) {
  // 每次挂载时执行，props 包含主应用传入的数据和容器 DOM
  const { container, onGlobalStateChange } = props;
  onGlobalStateChange((state) => console.log('收到主应用状态变更', state));
  ReactDOM.render(<App />, container ? container.querySelector('#root') : document.getElementById('root'));
}

export async function unmount(props) {
  // 卸载时必须清理：定时器、事件监听、全局状态
  const { container } = props;
  ReactDOM.unmountComponentAtNode(
    container ? container.querySelector('#root') : document.getElementById('root')
  );
}

// ===== Module Federation 配置（webpack.config.js）=====
const { ModuleFederationPlugin } = require('webpack').container;

module.exports = {
  plugins: [
    new ModuleFederationPlugin({
      name: 'host',
      // 声明远程子应用入口
      remotes: {
        remote_app: 'remote_app@http://localhost:3001/remoteEntry.js'
      },
      // shared 确保主子应用共用同一份 React 实例
      shared: {
        react: { singleton: true, requiredVersion: '^18.0.0' },
        'react-dom': { singleton: true, requiredVersion: '^18.0.0' }
      }
    })
  ]
};

// 运行时动态加载远程组件
const RemoteApp = React.lazy(() => import('remote_app/App'));

function App() {
  return (
    <Suspense fallback={<Loading />}>
      <RemoteApp />
    </Suspense>
  );
}

// ===== Wujie 使用 =====
import { startApp, preloadApp } from 'wujie';

// 可预加载子应用资源
preloadApp({ name: 'vue-app', url: 'http://localhost:3002' });

startApp({
  name: 'vue-app',
  url: 'http://localhost:3002',
  el: document.getElementById('micro-container'),
  sync: true // 主子应用路由同步
});

// ===== 跨应用通信：自定义事件 =====
// 主应用发送
window.dispatchEvent(new CustomEvent('micro-msg', {
  detail: { type: 'login', data: { userId: 123 } }
}));

// 子应用监听
window.addEventListener('micro-msg', (event) => {
  const { type, data } = event.detail;
  if (type === 'login') {
    console.log('收到登录事件', data);
  }
});
